long enumerate_media_entities(struct media_device *mdev, struct media_entity_desc __user *uent)
{
    struct media_entity_desc kent;
    int ret = 0;

    if (!mdev || !uent) {
        return -EINVAL;
    }

    memset(&kent, 0, sizeof(kent));

    if (copy_from_user(&kent, uent, sizeof(*uent))) {
        return -EFAULT;
    }

    kent = get_media_entity_by_id(mdev, kent.id);
    if (IS_ERR_OR_NULL(kent)) {
        return -EINVAL;
    }

    if (copy_to_user(uent, &kent, sizeof(kent))) {
        return -EFAULT;
    }

    return 0;
}

long enumerate_media_entities(struct media_device *mdev, struct media_entity_desc __user *uent)
{
    struct media_entity_desc kent;
    int ret;

    if (!mdev || !uent)
        return -EINVAL;

    memset(&kent, 0, sizeof(kent));
    kent.__pad = 0;

    ret = media_entity_get_by_id(mdev, kent.id, &kent);
    if (ret < 0)
        return ret;

    if (copy_to_user(uent, &kent, sizeof(kent)))
        return -EFAULT;

    return 0;
}

